/** How far ahead the overdue job looks when collecting due issues. */
export const OVERDUE_LOOKAHEAD_HOURS: number = 24;

/**
 * How long a deleted workspace stays restorable. After this many days the
 * workspace is gone — restore rejects it, and the retention sweep purges it.
 */
export const DELETED_WORKSPACE_RETENTION_DAYS: number = 30;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Deletions at or before this instant are past the restore window. */
export function deletedWorkspacePurgeCutoff(now: Date): Date {
  return new Date(
    now.getTime() - DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY,
  );
}

/** True once `archivedAt` is at least {@link DELETED_WORKSPACE_RETENTION_DAYS} × 24h old. */
export function isDeletedWorkspaceExpired(archivedAt: string, now: Date): boolean {
  const deletedAt = new Date(archivedAt).getTime();
  return (
    Number.isFinite(deletedAt) &&
    deletedAt <= deletedWorkspacePurgeCutoff(now).getTime()
  );
}

