/**
 * Audit writers for workspace deletion and restoration.
 *
 * Refcounted so `deleteOrganization` / `restoreOrganization` can attach them
 * for the duration of one `emit` without stacking a second writer on top of
 * the set `registerActivityListeners` already holds.
 */
let organizationAuditRefs = 0;
let detachOrganizationAudits: Unsubscribe | null = null;

export function retainOrganizationAuditListeners(): Unsubscribe {
  if (organizationAuditRefs === 0) {
    const offs: Unsubscribe[] = [
      subscribe("organization.deleted", (payload) =>
        record(payload.orgId, "organization.deleted", {
          actorId: payload.actorId,
          subjectKind: "organization",
          subjectId: payload.orgId,
          projectId: null,
          summary: `Deleted workspace ${payload.slug}`,
        }).then(() => undefined),
      ),
      subscribe("organization.restored", (payload) =>
        record(payload.orgId, "organization.restored", {
          actorId: payload.actorId,
          subjectKind: "organization",
          subjectId: payload.orgId,
          projectId: null,
          summary: `Restored workspace ${payload.slug}`,
        }).then(() => undefined),
      ),
    ];
    detachOrganizationAudits = () => {
      for (const off of offs) off();
    };
  }

  organizationAuditRefs += 1;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    organizationAuditRefs -= 1;
    if (organizationAuditRefs === 0) {
      detachOrganizationAudits?.();
      detachOrganizationAudits = null;
    }
  };
}

