}

/**
 * Brings a deleted workspace back during the retention window. The caller is
 * a user id: a deleted workspace has no resolvable `Actor`. A missing
 * workspace, a non-member, and a window that has already closed are the same
 * outcome — the workspace is gone.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) throw new NotFoundError("Organization", orgId);

  if (
    org.archivedAt !== null &&
    isDeletedWorkspaceExpired(org.archivedAt, new Date())
  ) {
    throw new NotFoundError("Organization", orgId);
  }

  const member = await memberRepo.findMember(orgId, userId);
  if (!member) throw new NotFoundError("Organization", orgId);

  const actor: Actor = { userId, orgId, role: member.role };
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:restore", orgResource(orgId));

  if (org.archivedAt === null) return org;

  const restored = await orgRepo.restoreOrg(orgId);
  await publishOrganizationLifecycle(
    "organization.restored",
    restored.id,
    userId,
    restored.slug,
  );
  return restored;
}

